					Size = UDim2.new(1, -4, 0, 18),
					Text = tostring(name or ""),
					Color = P.TextSoft,
					Size_ = 12.5,
					Weight = FW.SemiBold,
				});
				Title.TextSize = 12.5;
				Title.ZIndex = 15;

				local Body = UI.text({
